// Browser half of recipe acceptance. Can run against an existing MCP-created
// recipes.html without rebuilding or mutating the deck. Chromium or WebKit.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const pw=require(process.env.PLAYWRIGHT_MODULE||'playwright'),output=process.argv[2];
if(!output)throw Error('Provide the directory containing MCP-created recipes.html');
(async()=>{const engine=process.env.RECIPE_BROWSER||'chromium',browser=await pw[engine].launch({headless:true,timeout:20000,...(process.env.RECIPE_BROWSER_PATH?{executablePath:process.env.RECIPE_BROWSER_PATH}:engine==='chromium'&&process.env.CHROME_PATH?{executablePath:process.env.CHROME_PATH}:{})});
try{const page=await browser.newPage({viewport:{width:960,height:540}}),errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('file://'+path.join(output,'recipes.html'));await page.waitForFunction(()=>typeof KeynopeScene!=='undefined'&&typeof effectLines==='function');
const result=await page.evaluate(async()=>{await KeynopeScene.ensureFonts();const pages=JSON.parse(document.getElementById('keynope-data').textContent).pages;const reports=[];
for(let index=0;index<pages.length;index++){const scene=pages[index].scene,host=document.createElement('div');host.style.cssText='position:fixed;left:0;top:0;transform-origin:0 0;transform:scale(.5);z-index:9999';document.body.append(host);const view=KeynopeScene.mount(host,scene);await view.ready;reports.push({index,text:scene.objects.filter(o=>o.kind==='text').map(o=>o.text?.runs?.map(r=>r.text).join('')).join(' / '),diagnostics:view.diagnostics,resources:view.resourceCounts()});view.dispose();host.remove()}
const effects=pages.filter(p=>p.effect&&p.effect!=='none').map(p=>{let nonempty=0;const hashes=new Set();effectState.clear();for(let frame=0;frame<=160;frame+=2){const lines=effectLines(p,frame);if(lines.length)nonempty++;hashes.add(JSON.stringify(lines))}return {effect:p.effect,nonempty,distinct:hashes.size}});
return {reports,effects};});
fs.writeFileSync(path.join(output,engine+'-review.json'),JSON.stringify({result,errors},null,2));
assert.deepEqual(errors,[]);for(const e of result.effects){assert.ok(e.nonempty>0,'No painted frames: '+e.effect);assert.ok(e.distinct>1,'No motion: '+e.effect)}
const unexpected=result.reports.flatMap(r=>r.diagnostics.filter(d=>['text-overflow','table-cell-overflow','table-cell-cramped'].includes(d.code)).map(d=>({slide:r.index,...d})));
console.log(JSON.stringify({engine,effects:result.effects,overflow:unexpected},null,2));assert.deepEqual(unexpected,[],'Recipe text/table overflow');
for(const effect of ['cut','fade','push','wipe','dip-black','dip-white','tv-switch']){
 await page.evaluate(effect=>{const host=document.createElement('div');host.id='transition-proof';host.style.cssText='position:fixed;inset:0;background:#101828;z-index:99999';const incoming=document.createElement('div');incoming.style.cssText='position:absolute;inset:0;background:#14476b;color:white;font:60px system-ui;padding:80px;box-sizing:border-box';incoming.textContent='NEXT / '+effect;host.append(incoming);document.body.append(host);window.testTransition=KeynopeBuilds.slideTransition(host,incoming,{reducedMotion:()=>false});const old=document.createElement('div');old.style.cssText=incoming.style.cssText;old.style.background='#692c57';old.textContent='BEFORE';testTransition.hold(old);testTransition.play({effect,direction:'left',durationMs:1500});},effect);
 await page.waitForTimeout(650);await page.screenshot({path:path.join(output,engine+'-transition-'+effect+'.png')});await page.evaluate(()=>{testTransition.cancel();document.getElementById('transition-proof').remove()});
}
// Animated GIF must actually change frames, and reduced motion must hold frame zero.
const gif=await page.evaluate(async()=>{const pages=JSON.parse(document.getElementById('keynope-data').textContent).pages;const scene=pages.find(p=>p.scene.objects.some(o=>o.media?.frames?.length>1)).scene;const host=document.createElement('div');document.body.append(host);const view=KeynopeScene.mount(host,scene);await view.snapshotAt(0);const before=[...host.querySelectorAll('img')].map(i=>i.src);await view.snapshotAt(1600);const after=[...host.querySelectorAll('img')].map(i=>i.src);view.dispose();host.remove();return {changed:JSON.stringify(before)!==JSON.stringify(after)}});assert.ok(gif.changed,'GIF frames did not advance');
const live=await browser.newPage({viewport:{width:960,height:540}});await live.goto('file://'+path.join(output,'recipes.html'));await live.waitForFunction(()=>typeof pageIndex!=='undefined'&&modernPageView);await live.keyboard.press('ArrowRight');await live.waitForFunction(()=>pageIndex===1);await live.keyboard.press('ArrowRight');await live.waitForFunction(()=>pageIndex===2&&standaloneBuildPlayback);await live.waitForTimeout(400);const start=await live.evaluate(()=>({page:pageIndex,...standaloneBuildPlayback.snapshot()}));assert.equal(start.step,0);for(let i=1;i<=3;i++){await live.keyboard.press('ArrowRight');await live.waitForFunction(i=>pageIndex===2&&standaloneBuildPlayback.snapshot().step===i,i);await live.waitForTimeout(300)}await live.keyboard.press('ArrowRight');await live.waitForFunction(()=>pageIndex===3);await live.close();
const reduced=await browser.newPage({viewport:{width:960,height:540},reducedMotion:'reduce'});await reduced.goto('file://'+path.join(output,'recipes.html'));await reduced.waitForFunction(()=>modernPageView);const stopped=await reduced.evaluate(async()=>{const pages=JSON.parse(document.getElementById('keynope-data').textContent).pages;const scene=pages.find(p=>p.scene.objects.some(o=>o.media?.frames?.length>1)).scene;const host=document.createElement('div');document.body.append(host);const view=KeynopeScene.mount(host,scene);await view.ready;view.setTime(0);const before=[...host.querySelectorAll('img')].map(i=>i.src);view.setTime(1600);const after=[...host.querySelectorAll('img')].map(i=>i.src);view.dispose();host.remove();return JSON.stringify(before)===JSON.stringify(after)});assert.ok(stopped,'Reduced motion did not freeze GIF');await reduced.close();
console.log('PASS '+engine+': '+result.reports.length+' slides, 14 animated effects, all native typography/table bounds, transition captures, GIF frame advance/reduced motion and real player keyboard reveals');
}finally{await browser.close()}})().catch(e=>{console.error(e);process.exitCode=1});
